```rust
use warp::Filter;

let api = warp::path("search")
    .and(warp::get())
    .and(warp::filters::query::query())
    .map(|params: std::collections::HashMap<String, String>| {
        // Process the query parameters
        format!("Query parameters: {:?}", params)
    });
```

